import { edit_form_details } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    editFormDialog: Boolean,
    formInfo: Object
  },
  data() {
    return {
      formName: "",
      formDesc: "",
      loading: false
    };
  },
  watch: {
    editFormDialog: {
      async handler() {
        if (this.editFormDialog == true) {
          this.formName = this.formInfo.form_name;
          this.formDesc = this.formInfo.form_description;
        }
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    validate_data() {
      if (this.$refs.form.validate()) {
        this.edit_form();
      }
    },
    async edit_form() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(edit_form_details, {
          input: {
            form_id: this.formInfo.form_id,
            form_description: this.formDesc
          }
        }));
        var response = JSON.parse(result.data.edit_form_details);
        this.loading = false;
        if (response.Status == "success") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
